FILE PATH: roles/nginx/templates/nginx.conf.j2

FILE CONTENT:
```jinja2
#{{ ansible_managed }}
{% if ansible_os_family == 'RedHat' %} 
user              nginx;
{% endif %}
{% if ansible_os_family == 'Debian' %} 
user              www-data;
{% endif %}

worker_processes  {{ ansible_processor_count }};
pid        /var/run/nginx.pid;


events {
    worker_connections  {{ nginx_max_clients }};
}


http {
        ssl_protocols TLSv1 TLSv1.1 TLSv1.2;
        include /etc/nginx/mime.types;
        default_type application/octet-stream;

        access_log {{ nginx_log_dir}}/{{ nginx_access_log_name}};
        error_log {{ nginx_log_dir}}/{{ nginx_error_log_name}};

{% for k,v in nginx_http_params.iteritems() %}
        {{ k }}  {{ v }};
{% endfor %}

        gzip on;
        gzip_disable "msie6";

        include /etc/nginx/conf.d/*.conf;
        include /etc/nginx/sites-enabled/*;
}

```

Now analyze the template above and return the analysis JSON:
```json
{
  "variables_used": [],
  "bare_variables": [],
  "deprecated_tests": [],
  "notes": []
}
```

FILE PATH: roles/nginx/templates/site.j2

FILE CONTENT:
```jinja2
server {

{% if nginx_separate_logs_per_site == True %}
	access_log {{ nginx_log_dir}}/{{ item.server.server_name}}-{{ nginx_access_log_name}};
	error_log {{ nginx_log_dir}}/{{ item.server.server_name}}-{{ nginx_error_log_name}};
{% endif %}

{% for k,v in item.server.iteritems() %}
{% if k.find('location') == -1 and k != 'file_name' %}
{{ k }} {{ v }};
{% endif %}
{% endfor %} 

{% for k,v in item.server.iteritems() if k.find('location') != -1 %}
  location {{ v.name }} {
{% for x,y in v.iteritems() if x != 'name' %} 
      {{ x }} {{ y }};
{% endfor %}
  }
{% endfor %}
}


```

Now analyze the template above and return the analysis JSON:
```json
{
  "variables_used": [],
  "bare_variables": [],
  "deprecated_tests": [],
  "notes": []
}
```
